import random
import string
from typing import List

# This generator focuses on producing valid C strings for wildcard patterns and text inputs
# used by wildmatch/iwildmatch and arrays of strings used by wildmatch_array/litmatch_array.
# We emit one bytes blob that concatenates multiple NUL-terminated strings and raw integers
# that the fuzz harness can consume sequentially via FUZZ_PARAM_STR and FUZZ_PARAM(unsigned int).
#
# Layout (all NUL-terminated where noted):
# 1) pattern for wildmatch (cstr)
# 2) text for wildmatch (cstr)
# 3) pattern for iwildmatch (cstr)
# 4) text for iwildmatch (cstr)
# 5) unsigned int raw for array length selection (4 bytes LE)
# 6) s0..s5 strings (6 cstr)
# 7) unsigned int wraw for where selection (4 bytes LE)
# 8) pattern for wildmatch_array (cstr)
#
# All strings are NUL-terminated ASCII/UTF-8, total size <= 4096 bytes.

MAX_TOTAL = 4096

PRINTABLE_SAFE = ''.join(ch for ch in (string.ascii_letters + string.digits + string.punctuation + ' ') if ch != '\x00')

def rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]

def make_literal(rng: random.Random, min_len: int = 0, max_len: int = 32) -> str:
    n = rng.randint(min_len, max_len)
    alph = string.ascii_letters + string.digits
    punc = "-_.:,/\\+@#%(){}$^~"
    chars = alph + punc + ' '
    s = ''.join(rng.choice(chars) for _ in range(n))
    if n > 0 and rng.random() < 0.5:
        s = s.strip()
    return s

def make_class(rng: random.Random) -> str:
    # Character class like [abc], [a-z], [!0-9]
    parts: List[str] = []
    neg = rng.random() < 0.3
    if rng.random() < 0.6:
        # ranges
        for _ in range(rng.randint(1, 3)):
            a = rng.choice(string.ascii_letters + string.digits)
            b = rng.choice(string.ascii_letters + string.digits)
            if a > b:
                a, b = b, a
            parts.append(f"{a}-{b}")
    else:
        pool = string.ascii_letters + string.digits + "-_:."
        k = rng.randint(1, 6)
        for _ in range(k):
            ch = rng.choice(pool)
            parts.append(ch)
    content = ''.join(parts) or 'a'
    prefix = '!' if neg else ''
    return '[' + prefix + content + ']'

def escape_literal_for_glob(lit: str) -> str:
    out = []
    for ch in lit:
        if ch in "*?[]\\":
            out.append('\\' + ch)
        else:
            out.append(ch)
    return ''.join(out)

def make_glob_segment(rng: random.Random) -> str:
    t = rng.random()
    if t < 0.2:
        return '*'
    if t < 0.35:
        return '**' if rng.random() < 0.3 else '*?'
    if t < 0.5:
        return '?'
    if t < 0.7:
        return make_class(rng)
    lit = make_literal(rng, 1, 8)
    return escape_literal_for_glob(lit)

def make_glob(rng: random.Random, max_segs: int = 8) -> str:
    segs = rng.randint(1, max_segs)
    parts: List[str] = []
    for i in range(segs):
        parts.append(make_glob_segment(rng))
        if i != segs - 1 and rng.random() < 0.25:
            parts.append('/' if rng.random() < 0.7 else '\\')
    pat = ''.join(parts)
    # sometimes append literal markers that typical glob treats as literals
    if rng.random() < 0.15:
        pat = '^' + pat
    if rng.random() < 0.15:
        pat = pat + '$'
    return pat

def make_text_matching(rng: random.Random, pat: str) -> str:
    # Heuristic synthesizer to produce a text likely to match the glob
    out: List[str] = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == '*':
            k = rng.randint(0, 6)
            pool = string.ascii_letters + string.digits + "-_.:/\\"
            out.append(''.join(rng.choice(pool) for _ in range(k)))
            i += 1
        elif c == '?':
            pool = string.ascii_letters + string.digits + "-_.:/\\"
            out.append(rng.choice(pool))
            i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < len(pat) and pat[j] in ('!', '^'):
                neg = True
                j += 1
            chars = []
            # parse until closing ]
            while j < len(pat) and pat[j] != ']':
                if (j + 2 < len(pat)) and (pat[j+1] == '-') and (pat[j+2] != ']'):
                    a, b = pat[j], pat[j+2]
                    if a <= b:
                        chars.extend([chr(x) for x in range(ord(a), ord(b)+1)])
                    else:
                        chars.extend([a, b])
                    j += 3
                else:
                    if pat[j] == '\\' and j + 1 < len(pat):
                        chars.append(pat[j+1])
                        j += 2
                    else:
                        chars.append(pat[j])
                        j += 1
            pool = string.ascii_letters + string.digits + "-_.:/\\"
            if not chars:
                chars = list(pool)
            if neg:
                choices = [ch for ch in pool if ch not in chars]
                if not choices:
                    choices = list(pool)
                out.append(rng.choice(choices))
            else:
                out.append(rng.choice(chars))
            i = j + 1 if j < len(pat) and pat[j] == ']' else j
        elif c == '\\' and i + 1 < len(pat):
            out.append(pat[i+1])
            i += 2
        else:
            out.append(c)
            i += 1
    s = ''.join(out)
    return s[:256]

def make_case_variant(rng: random.Random, s: str) -> str:
    out = []
    for ch in s:
        if ch.isalpha() and rng.random() < 0.5:
            ch = ch.upper() if ch.islower() else ch.lower()
        out.append(ch)
    return ''.join(out)

def pack_u32_le(v: int) -> bytes:
    return bytes((v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF, (v >> 24) & 0xFF))

def capped_concat(parts: List[bytes]) -> bytes:
    out = b''
    for p in parts:
        if len(out) + len(p) > MAX_TOTAL:
            break
        out += p
    return out

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # 1) wildmatch pattern/text
    pat1 = make_glob(rng)
    txt1 = make_text_matching(rng, pat1)
    if rng.random() < 0.25:
        if txt1:
            idx = rng.randrange(len(txt1))
            repl_pool = ''.join(ch for ch in PRINTABLE_SAFE if ch != txt1[idx])
            txt1 = txt1[:idx] + rng.choice(repl_pool) + txt1[idx+1:]
        else:
            txt1 = 'no-match'

    # 2) iwildmatch pattern/text
    pat2 = make_glob(rng)
    base_txt2 = make_text_matching(rng, pat2)
    txt2 = make_case_variant(rng, base_txt2)

    # 3) Array length raw: choose 0..6 via raw % 7
    M = rng.randint(0, 6)
    raw_len = M  # mod 7 -> M

    # 4) s0..s5 strings
    s_list: List[str] = []
    for i in range(6):
        if i < M:
            if rng.random() < 0.5:
                s = make_text_matching(rng, pat1 if rng.random() < 0.5 else pat2)
            else:
                s = make_literal(rng, 0, 20)
        else:
            s = ''
        s_list.append(s)

    # 5) where selection
    where = rng.randrange(M) if M > 0 else 0

    # 6) pattern for wildmatch_array
    if rng.random() < 0.4:
        pat_arr = pat1
    elif rng.random() < 0.5:
        pat_arr = pat2
    else:
        pat_arr = make_glob(rng)

    parts: List[bytes] = []

    def add_cstr(s: str):
        parts.append(s.encode('utf-8', 'ignore') + b'\x00')

    add_cstr(pat1)
    add_cstr(txt1)
    add_cstr(pat2)
    add_cstr(txt2)
    parts.append(pack_u32_le(raw_len))
    for s in s_list:
        add_cstr(s)
    parts.append(pack_u32_le(where))
    add_cstr(pat_arr)

    blob = capped_concat(parts)
    if not blob:
        blob = b"\x00"
    return blob
